      "severity": "major",
      "witnessCode": "import { strict as assert } from 'node:assert';\nimport normalizeUrl from '../index.js';\n\nconst url = 'http://example.com/?b=1%20&a=2';\nconst result = normalizeUrl(url, { sortQueryParameters: true });\nassert.strictEqual(result, 'http://example.com/?a=2&b=1 ');"
